mapper.select:
SELECT  
FROM tb_product A
WHERE


        A.USER_NO = #{userNo}


        A.WHOLESALER_NO = #{userNo}


        1 = 0




    AND A.SALE_STATUS = #{saleStatus}

ORDER BY A.REGIST_DT DESC
LIMIT #{offset}, #{limit}

SELECT  
FROM tb_product A





            AND A.SALE_STATUS = 1




            AND A.SALE_STATUS IN (1,10,99)




        AND A.CATEGORY_GROUP = #{categoryGroup}



        AND A.CATEGORY_MID = #{categoryMid}



        AND A.CATEGORY_SCLS = #{categoryScls}




        AND A.AREA_GROUP = #{areaGroup}



        AND A.AREA_MID = #{areaMid}



        AND A.AREA_SCLS = #{areaScls}




        AND A.PRICE >= #{minPrice}



        AND A.PRICE <= #{maxPrice}


ORDER BY A.REGIST_DT DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(SALE_STATUS) AS totalCount, SUM(CASE WHEN SALE_STATUS = '0' THEN 1 ELSE 0 END) AS reguestCount, SUM(CASE WHEN SALE_STATUS IN ('1', '10') THEN 1 ELSE 0 END) AS processingCount, SUM(CASE WHEN SALE_STATUS = '99' THEN 1 ELSE 0 END) AS completedCount FROM tb_product WHERE
USER_NO = #{userNo}
WHOLESALER_NO = #{userNo}
1 = 0

SELECT A.PRODUCT_ID, A.TITLE, IFNULL(A.QUANTITY, 0) AS QUANTITY, A.UNIT_CODE, (SELECT CODE_NM FROM op_code WHERE GROUP_ID = 'R010620' AND CODE = A.UNIT_CODE) AS UNIT_CODE_NM, A.AREA_GROUP, A.AREA_MID, A.AREA_SCLS, (SELECT CODE_NM FROM op_code WHERE GROUP_ID = A.AREA_GROUP AND CODE = A.AREA_MID) AS AREA_MID_NM, (SELECT SCLAS_NM FROM op_sclas_code WHERE GROUP_ID = A.AREA_GROUP AND CODE = A.AREA_MID AND SCLAS_CODE = A.AREA_SCLS) AS AREA_SCLS_NM, A.SALE_STATUS, (SELECT CODE_NM FROM op_code WHERE GROUP_ID = 'R010630' AND CODE = A.SALE_STATUS) AS SALE_STATUS_NM, A.REGIST_DT, A.DESIRED_SHIPPING_DATE, (SELECT USER_ID FROM op_user WHERE USER_NO = A.USER_NO) AS USER_ID FROM tb_product A WHERE
A.USER_NO = #{userNo}
A.WHOLESALER_NO = #{userNo}
1 = 0
ORDER BY A.REGIST_DT DESC LIMIT 3
